import ast,hashlib,io,json,sys
from pathlib import Path
raw=Path('/tmp/authbus-production-p01-source-r1/input.public.json').read_bytes()
assert len(raw)==328295 and hashlib.sha256(raw).hexdigest()=='d0bab0c53bd92524b6a7ca7c3d5bc7ab60b26eb742c4a8e2c6f094c62e3f7b59'
source=bytes.fromhex('')
assert hashlib.sha256(source).hexdigest()=='5e4463d260402989b44833ebe2a899f37c7fa6b9fe12df18e8975bcc87860e00'
root=Path('/tmp/authbus-production-p01-source-r2')
root.mkdir(mode=0o700)
with (root/'project_public_registration.py').open('xb') as f:f.write(source)
tree=ast.parse(source,filename='project_public_registration.py')
imports=[alias.name for node in ast.walk(tree) if isinstance(node,ast.Import) for alias in node.names]
assert imports==['hashlib','json','sys','time']
code=compile(tree,'project_public_registration.py','exec')
old=(sys.stdin,sys.stdout,sys.stderr)
in_stream=io.TextIOWrapper(io.BytesIO(raw),encoding='utf-8')
out_memory=io.BytesIO();err_memory=io.BytesIO()
out_stream=io.TextIOWrapper(out_memory,encoding='utf-8');err_stream=io.TextIOWrapper(err_memory,encoding='utf-8')
exit_code=None
try:
 sys.stdin,sys.stdout,sys.stderr=in_stream,out_stream,err_stream
 try:exec(code,{'__name__':'__main__'})
 except SystemExit as e:exit_code=e.code
 finally:out_stream.flush();err_stream.flush()
 stdout=out_memory.getvalue();stderr=err_memory.getvalue()
finally:sys.stdin,sys.stdout,sys.stderr=old
for name,data in [('input.public.json',raw),('stdout.original.json',stdout),('stderr.original.txt',stderr)]:
 with (root/name).open('xb') as f:f.write(data)
before=json.loads(Path('/tmp/authbus-production-p01-source-r1/stdout.original.json').read_bytes())
after=json.loads(stdout)
before_other={k:v for k,v in before.items() if k not in ('schema','proposedNewCreateOnlyHostRegistrations')}
after_other={k:v for k,v in after.items() if k not in ('schema','proposedNewCreateOnlyHostRegistrations')}
assert before_other==after_other
assert before['proposedNewCreateOnlyHostRegistrations'][1:]==after['proposedNewCreateOnlyHostRegistrations'][1:]
mac=after['proposedNewCreateOnlyHostRegistrations'][0]
assert mac['host']=='mac' and mac['proposalOnlyNewRoot'].startswith('/Volumes/T5/hepta-vnext-recovery-20261013/')
for key in ('serverBinaryPath','serverConfigurationPath','serverDataPath','backupRegistrationPath','backupDataPath','publicRegistrationPath'):
 assert mac[key].startswith(mac['proposalOnlyNewRoot']+'/')
assert mac['clientCredentialGenerationPath']==before['proposedNewCreateOnlyHostRegistrations'][0]['clientCredentialGenerationPath']
assert mac['proposedNewClientFiles']==before['proposedNewCreateOnlyHostRegistrations'][0]['proposedNewClientFiles']
assert mac['volumeBinding']['volumeUUID']=='FB804D1B-24CB-4D6E-AEA7-A9E180807758'
assert mac['volumeBinding']['expectedVolumeDevice']=='16777244'
report={'schema':'heptabao.authbus-p01-t5-increment-local-execution.r2','candidateExitCode':exit_code,'sourceBytes':len(source),'sourceSha256':hashlib.sha256(source).hexdigest(),'inputBytes':len(raw),'inputSha256':hashlib.sha256(raw).hexdigest(),'stdoutBytes':len(stdout),'stdoutSha256':hashlib.sha256(stdout).hexdigest(),'stderrBytes':len(stderr),'stderrSha256':hashlib.sha256(stderr).hexdigest(),'sourceImports':imports,'exactOldOtherHostProposalsPreserved':True,'exactOldOtherProjectionFieldsPreserved':True,'macClientCredentialFilesUnchanged':True,'macServerBinaryDataBackupOnT5':True,'noHostCalls':True,'noSqlite':True,'noChild':True,'noNetwork':True,'onlyLocalPublicSourceAndEvidence':True}
with (root/'execution.public.json').open('x') as f:json.dump(report,f,indent=2);f.write('\n')
print(json.dumps(report,sort_keys=True))
if stderr:print(stderr.decode(),file=sys.stderr,end='')
sys.exit(0 if exit_code==0 else 1)
